<?php require_once __DIR__.'/../includes/functions.php';if($_SERVER['REQUEST_METHOD']!=='POST')go('/laporwarga/login.php');check_csrf();$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$s=db()->prepare('SELECT * FROM users WHERE email=? AND status_akun=1');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($password,$u['password'])){flash('error','Email atau kata sandi salah, atau akun tidak aktif.');go('/laporwarga/login.php');}session_regenerate_id(true);$_SESSION['user']=['id_user'=>(int)$u['id_user'],'nama_lengkap'=>$u['nama_lengkap'],'email'=>$u['email'],'role'=>$u['role']];log_activity('login','Login berhasil');go(role_home());